import{_ as a,o as e,c as d,a0 as n}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"架构总览","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/index.md","filePath":"advanced/index.md","lastUpdated":1793354613000}'),s={name:"advanced/index.md"};function o(i,t,r,c,l,p){return e(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><p>本页说明进程与端口划分、实时事件注册、房间状态分层与全局取舍。各子系统细节见文末导航。</p><h2 id="进程与端口" tabindex="-1">进程与端口 <a class="header-anchor" href="#进程与端口" aria-label="Permalink to &quot;进程与端口&quot;">​</a></h2><p>一个 Go 后端进程承担 API、前端静态资源与实时通信，另有一个 LiveKit 伴生进程负责语音媒体。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器（React SPA）</span></span>
<span class="line"><span>   │  HTTP REST + Socket.IO</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>zviewer-backend（Go，:3333，统一入口）</span></span>
<span class="line"><span>   ├── REST /api/*            鉴权、房间、挂载、解析、音乐…</span></span>
<span class="line"><span>   ├── Socket.IO /socket.io   房间实时同步</span></span>
<span class="line"><span>   ├── 静态托管                frontend/dist + SPA 回退</span></span>
<span class="line"><span>   ├── 内置媒体服务            RTMP 3334 → HTTP-FLV 3335（进程内）</span></span>
<span class="line"><span>   ├── /live 反代              → 3335</span></span>
<span class="line"><span>   ├── /rtc 反代               → livekit-server 信令 3336</span></span>
<span class="line"><span>   └── 网易云接口              进程内实现，不监听端口</span></span>
<span class="line"><span>媒体 3333/udp、3337/tcp → livekit-server；TURN/TLS 3338</span></span></code></pre></div><table tabindex="0"><thead><tr><th>端口</th><th>用途</th></tr></thead><tbody><tr><td>3333/tcp</td><td>页面、API、WebSocket、<code>/live</code> 与 <code>/rtc</code> 反代</td></tr><tr><td>3333/udp</td><td>语音媒体</td></tr><tr><td>3334/tcp</td><td>OBS RTMP 推流</td></tr><tr><td>3335/tcp</td><td>HTTP-FLV 拉流（内部，经 <code>/live</code> 对外）</td></tr><tr><td>3336/tcp</td><td>LiveKit 信令（内部）</td></tr><tr><td>3337/tcp</td><td>语音 ICE/TCP</td></tr><tr><td>3338/tcp</td><td>语音 TURN/TLS（可选）</td></tr></tbody></table><ul><li><strong>单端口 3333</strong>：生产模式所有页面流量走 3333（HTTP 或 HTTPS），无跨域问题。</li><li><strong>RTMP 3334 独立</strong>：RTMP 无法与 HTTP 复用端口；拉流走内部 3335，由 <code>/live</code> 反代，3335 无需暴露。</li><li><strong>内置媒体服务</strong>：RTMP / FLV 由后端进程内的 Go 实现承担，不依赖外部媒体服务器；<code>STREAM_PUSH_ENABLED=0</code> 时 3334/3335 都不监听。</li><li><strong>网易云接口</strong>：一起听所需接口在进程内实现，没有独立服务地址，也不存在「音乐服务未启动」这种状态。</li><li><strong>livekit-server 伴生进程</strong>：语音媒体由独立 LiveKit 承载，后端只签发凭证与执行管理动作。见<a href="/advanced/voice">语音聊天链路</a>。</li></ul><h2 id="实时事件注册" tabindex="-1">实时事件注册 <a class="header-anchor" href="#实时事件注册" aria-label="Permalink to &quot;实时事件注册&quot;">​</a></h2><p>实时层由 <code>internal/sio</code>（Socket.IO 协议的自实现）与 <code>internal/realtime</code>（事件总线与广播）组成，业务事件在各域的 <code>*_handlers.go</code> 里用 <code>sc.On(事件名, …)</code> 注册，每个文件只挂自己的事件名。ack 统一为 <code>{ success, message?, code?, data? }</code>。</p><p>连接鉴权在握手阶段完成，JWT 取用分两种：</p><ul><li><code>handshake.auth.agent === &#39;zcontrol-cli&#39;</code> 直接放行并标记为 CLI 代理，见 <a href="/advanced/cli-protocol">CLI 代理协议</a>。</li><li>其余按 <strong>cookie → <code>handshake.auth.token</code> → <code>handshake.query.token</code></strong> 顺序校验，失败拒绝握手。</li></ul><h2 id="状态分层-内存权威副本-节流落盘" tabindex="-1">状态分层：内存权威副本 + 节流落盘 <a class="header-anchor" href="#状态分层-内存权威副本-节流落盘" aria-label="Permalink to &quot;状态分层：内存权威副本 + 节流落盘&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>载体</th><th>特点</th></tr></thead><tbody><tr><td>运行时权威副本</td><td>内存中的房间状态</td><td>影片列表、当前影片、播放状态、字幕缓存；读永远走内存</td></tr><tr><td>播放记忆</td><td>内存 + <code>PlaybackState</code> 表</td><td>状态写入节流 2s、心跳兜底 10s；退出前冲刷，最多丢 2s</td></tr><tr><td>持久化</td><td>Room / Movie / PlaybackState / MusicQueueItem 等表</td><td>重启后从库里恢复</td></tr></tbody></table><p>播放进度靠一条推算公式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actualCurrentTime = currentTime + (Date.now() - lastUpdatedAt) / 1000 × playbackRate × (isPlaying ? 1 : 0)</span></span></code></pre></div><p>超过 duration 时收敛为 <code>currentTime = duration, isPlaying = false</code>。房主短暂断线时服务器凭此继续推算，观众不中断；房主重连后取回状态继续担任同步源。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>技术</th></tr></thead><tbody><tr><td>前端</td><td>React 18 + TypeScript + Vite + Tailwind CSS + Zustand</td></tr><tr><td>后端</td><td>Go 1.26，<code>net/http</code> + 自实现的 Socket.IO 协议</td></tr><tr><td>桌面壳</td><td>Go + Wails（Windows，<code>desktop/</code>）</td></tr><tr><td>数据库</td><td>SQLite（纯 Go 驱动、WAL），SQL 手写，无 ORM</td></tr><tr><td>流媒体</td><td>内置媒体服务（RTMP / HTTP-FLV，进程内）</td></tr><tr><td>音视频</td><td>浏览器端重封装 / 转码（playsvideo，随前端分发）</td></tr><tr><td>语音</td><td>LiveKit（伴生进程，WebRTC）</td></tr><tr><td>音乐</td><td>进程内网易云接口实现</td></tr><tr><td>CLI</td><td>Go（独立仓库 ZViewer CLI）</td></tr></tbody></table><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><ul><li><strong>零外部依赖</strong>：媒体服务、网易云接口、Socket.IO 协议都在进程内，单文件版丢到任意机器即可运行；服务器端不转码，容器里不需要 FFmpeg。</li><li><strong>配置集中</strong>：数据库、证书、上传都在 <code>config/</code>，更新不覆盖，备份这一个目录即可。</li><li><strong>计算放浏览器</strong>：字幕提取、容器重封装、音轨转码均在浏览器完成，服务器只做转发与解析。</li><li><strong>一份数据库口径</strong>：结构只由 <code>schema.sql</code> 定义，启动时只校验不建表，缺表直接退出。</li></ul><h2 id="分区导航" tabindex="-1">分区导航 <a class="header-anchor" href="#分区导航" aria-label="Permalink to &quot;分区导航&quot;">​</a></h2><p><a href="/advanced/sync">房间同步</a> · <a href="/advanced/voice">语音链路</a> · <a href="/advanced/video-pipeline">视频源与 API</a> · <a href="/advanced/music-pipeline">音乐管线</a> · <a href="/advanced/cli-protocol">CLI 代理协议</a> · <a href="/advanced/theme-system">主题系统</a> · <a href="/advanced/https">HTTPS 证书</a> · <a href="/advanced/auth">鉴权与权限</a> · <a href="/advanced/api">REST API</a> · <a href="/advanced/env">环境变量</a> · <a href="/advanced/build-update">构建与更新</a></p>`,22)])])}const v=a(s,[["render",o]]);export{u as __pageData,v as default};
